162	// TruthyCondition represents a truthy check on a boolean parameter.
163	// In CUE, this generates `if parameter.name` instead of `if parameter.name == true`.
164	type TruthyCondition struct {
165		baseCondition
166		paramName string
167	}
168	
169	// ParamName returns the parameter name being checked.
170	func (t *TruthyCondition) ParamName() string { return t.paramName }
