24	// baseParam provides common parameter functionality.
25	type baseParam struct {
26		name         string
27		paramType    ParamType
28		required     bool // when true, emits "!" marker — user must explicitly provide this field in input
29		optional     bool // when true, emits "?" marker — field may be absent from input
30		defaultValue any
31		description  string
32		short        string // short flag alias (e.g. "i" → // +short=i)
33		ignore       bool   // when true, emits // +ignore directive
34	}
35	
36	func (p *baseParam) expr()      {}
37	func (p *baseParam) value()     {}
38	func (p *baseParam) condition() {}
39	
40	func (p *baseParam) Name() string           { return p.name }
41	func (p *baseParam) IsRequired() bool       { return p.required }
42	func (p *baseParam) IsOptional() bool       { return p.optional }
43	func (p *baseParam) HasDefault() bool       { return p.defaultValue != nil }
44	func (p *baseParam) GetDefault() any        { return p.defaultValue }
45	func (p *baseParam) GetDescription() string { return p.description }
46	func (p *baseParam) GetShort() string       { return p.short }
47	func (p *baseParam) IsIgnore() bool         { return p.ignore }
