49	// IsSet returns a condition that checks if the parameter has a value.
50	// This is used with SetIf for conditional field assignment.
51	func (p *baseParam) IsSet() Condition {
52		return &IsSetCondition{paramName: p.name}
53	}
54	
55	// NotSet returns a condition that checks if the parameter is not set.
56	// This generates `if parameter["name"] == _|_` in CUE.
57	func (p *baseParam) NotSet() Condition {
58		return Not(&IsSetCondition{paramName: p.name})
59	}
60	
61	// Eq creates a condition that compares this parameter to a literal value.
62	// Example: replicas.Eq(3) generates: parameter.replicas == 3
63	func (p *baseParam) Eq(val any) Condition {
64		return &ParamCompareCondition{paramName: p.name, op: "==", value: val}
65	}
66	
67	// Ne creates a condition that checks if this parameter is not equal to a value.
68	// Example: status.Ne("error") generates: parameter.status != "error"
69	func (p *baseParam) Ne(val any) Condition {
70		return &ParamCompareCondition{paramName: p.name, op: "!=", value: val}
71	}
72	
73	// Gt creates a condition that checks if this parameter is greater than a value.
74	// Example: replicas.Gt(1) generates: parameter.replicas > 1
75	func (p *baseParam) Gt(val any) Condition {
76		return &ParamCompareCondition{paramName: p.name, op: ">", value: val}
77	}
78	
79	// Gte creates a condition that checks if this parameter is greater than or equal to a value.
80	// Example: replicas.Gte(1) generates: parameter.replicas >= 1
81	func (p *baseParam) Gte(val any) Condition {
82		return &ParamCompareCondition{paramName: p.name, op: ">=", value: val}
83	}
84	
85	// Lt creates a condition that checks if this parameter is less than a value.
86	// Example: replicas.Lt(10) generates: parameter.replicas < 10
87	func (p *baseParam) Lt(val any) Condition {
88		return &ParamCompareCondition{paramName: p.name, op: "<", value: val}
89	}
90	
91	// Lte creates a condition that checks if this parameter is less than or equal to a value.
92	// Example: replicas.Lte(10) generates: parameter.replicas <= 10
93	func (p *baseParam) Lte(val any) Condition {
94		return &ParamCompareCondition{paramName: p.name, op: "<=", value: val}
95	}
