97	// ParamCompareCondition represents a comparison between a parameter and a value.
98	type ParamCompareCondition struct {
99		baseCondition
100		paramName string
101		op        string
102		value     any
103	}
104	
105	// ParamName returns the parameter name being compared.
106	func (c *ParamCompareCondition) ParamName() string { return c.paramName }
107	
