508	// writeValidator writes a CUE _validate* block.
509	// Example output:
510	//
511	//	_validateTenantName: {
512	//	    "tenantName must not end with a hyphen": true
513	//	    if tenantName =~ ".*-$" {
514	//	        "tenantName must not end with a hyphen": false
515	//	    }
516	//	}
517	func (g *CUEGenerator) writeValidator(sb *strings.Builder, v *Validator, depth int) {
518		indent := strings.Repeat(g.indent, depth)
519		inner := strings.Repeat(g.indent, depth+1)
520		inner2 := strings.Repeat(g.indent, depth+2)
521	
522		// Determine the CUE variable name
523		name := v.CUEName()
524		if name == "" {
525			// Auto-generate from message — use a simple underscore-prefixed name
526			name = "_validate"
527		}
528	
529		if v.GuardCondition() != nil {
530			// Guarded validator: wrap in if guard { ... }
531			guardCUE := g.conditionToCUE(v.GuardCondition())
532			sb.WriteString(fmt.Sprintf("%sif %s {\n", indent, guardCUE))
533			sb.WriteString(fmt.Sprintf("%s%s: {\n", inner, name))
534			sb.WriteString(fmt.Sprintf("%s%q: true\n", inner2, v.Message()))
535			if v.FailCondition() != nil {
536				failCUE := g.conditionToCUE(v.FailCondition())
537				sb.WriteString(fmt.Sprintf("%sif %s {\n", inner2, failCUE))
538				sb.WriteString(fmt.Sprintf("%s\t%q: false\n", inner2, v.Message()))
539				sb.WriteString(fmt.Sprintf("%s}\n", inner2))
540			}
541			sb.WriteString(fmt.Sprintf("%s}\n", inner))
542			sb.WriteString(fmt.Sprintf("%s}\n", indent))
543		} else {
544			// Unguarded validator
545			sb.WriteString(fmt.Sprintf("%s%s: {\n", indent, name))
546			sb.WriteString(fmt.Sprintf("%s%q: true\n", inner, v.Message()))
547			if v.FailCondition() != nil {
548				failCUE := g.conditionToCUE(v.FailCondition())
549				sb.WriteString(fmt.Sprintf("%sif %s {\n", inner, failCUE))
550				sb.WriteString(fmt.Sprintf("%s\t%q: false\n", inner, v.Message()))
551				sb.WriteString(fmt.Sprintf("%s}\n", inner))
552			}
553			sb.WriteString(fmt.Sprintf("%s}\n", indent))
554		}
555	}
556	
557	// writeConditionalParamBlock writes conditional parameter branches.
558	// Example output:
559	//
560	//	if existingResources == false {
561	//	    forceDestroy: *false | bool
562	//	}
563	//	if existingResources == true {
564	//	    forceDestroy?: bool
565	//	}
566	func (g *CUEGenerator) writeConditionalParamBlock(sb *strings.Builder, block *ConditionalParamBlock, depth int) {
567		indent := strings.Repeat(g.indent, depth)
568	
569		for _, branch := range block.Branches() {
570			condCUE := g.conditionToCUE(branch.Condition())
571			sb.WriteString(fmt.Sprintf("%sif %s {\n", indent, condCUE))
572	
573			// Write params inside the conditional block
574			for _, param := range branch.GetParams() {
575				g.writeParam(sb, param, depth+1)
576			}
577	
578			// Write validators inside the conditional block
579			for _, v := range branch.GetValidators() {
580				g.writeValidator(sb, v, depth+1)
581			}
582	
583			sb.WriteString(fmt.Sprintf("%s}\n", indent))
