func TestScratchRender(t *testing.T) {
	gen := NewCUEGenerator()

	// --- FailWhen(IsEmpty) => two false blocks ---
	tags := Array("tags").Optional()
	v := Validate("tags required").WithName("_validateTags").FailWhen(tags.IsEmpty())
	comp := NewComponent("test").Params(tags).Validators(v)
	cue := gen.GenerateParameterSchema(comp)
	t.Logf("FailWhen(IsEmpty):\n%s", cue)
	wantAbsent := `if parameter["tags"] == _|_ {`
	wantEmpty := `if parameter["tags"] != _|_ if len(parameter["tags"]) == 0 {`
	if !containsStr(cue, wantAbsent) || !containsStr(cue, wantEmpty) {
		t.Errorf("FailWhen(IsEmpty) missing branches:\n%s", cue)
	}

	// --- OneOf Optional + Default => no ? marker ---
	gen2 := NewCUEGenerator()
	oneof := OneOf("driver").Discriminator("driver").Optional().Default("local").
		Variants(Variant("local"), Variant("remote"))
	comp2 := NewComponent("t2").Params(oneof)
	cue2 := gen2.GenerateParameterSchema(comp2)
	t.Logf("OneOf opt+default:\n%s", cue2)
	if !containsStr(cue2, `driver: *"local" | "remote"`) {
		t.Errorf("OneOf opt+default should have no ? marker:\n%s", cue2)
	}

	// --- OneOf Optional no default => ? marker ---
	gen3 := NewCUEGenerator()
	oneof2 := OneOf("driver").Discriminator("driver").Optional().
		Variants(Variant("local"), Variant("remote"))
	cue3 := gen3.GenerateParameterSchema(NewComponent("t3").Params(oneof2))
	t.Logf("OneOf opt nodefault:\n%s", cue3)
	if !containsStr(cue3, `driver?: "local" | "remote"`) {
		t.Errorf("OneOf opt no-default should have ? marker:\n%s", cue3)
	}
}

func containsStr(s, sub string) bool {
	return len(s) >= len(sub) && (indexStr(s, sub) >= 0)
}

func indexStr(s, sub string) int {
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return i
		}
	}
	return -1
